const snippets={"Python": ["from typing import List", "", "class Solution:", "", "    def findKthLargest(self, nums: List[int], k: int) -> int:", "", "        def quick_sort(l: int, r: int) -> int:", "            if l == r:", "                return nums[l]", "            (i, j) = (l - 1, r + 1)", "            x = nums[l + r >> 1]", "            while i < j:", "                while 1:", "                    i += 1", "                    if nums[i] >= x:", "                        break", "                while 1:", "                    j -= 1", "                    if nums[j] <= x:", "                        break", "                if i < j:", "                    (nums[i], nums[j]) = (nums[j], nums[i])", "            if j < k:", "                return quick_sort(j + 1, r)", "            return quick_sort(l, j)", "        n = len(nums)", "        k = n - k", "        return quick_sort(0, n - 1)"], "Java": ["import java.util.*;", "class Solution {", "    private int[] nums;", "    private int k;", "", "    public int findKthLargest(int[] nums, int k) {", "        this.nums = nums;", "        this.k = nums.length - k;", "        return quickSort(0, nums.length - 1);", "    }", "", "    private int quickSort(int l, int r) {", "        if (l == r) {", "            return nums[l];", "        }", "        int i = l - 1, j = r + 1;", "        int x = nums[(l + r) >>> 1];", "        while (i < j) {", "            while (nums[++i] < x) {", "            }", "            while (nums[--j] > x) {", "            }", "            if (i < j) {", "                int t = nums[i];", "                nums[i] = nums[j];", "                nums[j] = t;", "            }", "        }", "        if (j < k) {", "            return quickSort(j + 1, r);", "        }", "        return quickSort(l, j);", "    }", "}"]};
